<div class="flex flex-col gap-1 bg-surface-container-low rounded-lg px-3 py-2.5" aria-live="polite"><span class="font-label-sm text-label-sm uppercase tracking-wider text-secondary">Already booked</span><span id="slots-text" class="font-body-sm text-body-sm text-on-surface">Loading...</span><span id="slots-warn" class="hidden font-body-sm text-body-sm font-semibold" style="color:var(--warn-fg)"></span></div>
<div class="flex items-center justify-between bg-surface-container-low rounded-lg px-3 py-2.5"><span class="font-label-md text-label-md text-on-surface-variant" id="total-label">Estimated total</span><span id="total" class="font-title-md text-title-md text-primary font-bold">₱150</span></div><p id="open-note" class="hidden font-body-sm text-body-sm text-on-surface-variant">Open time has no fixed end. Staff start the clock when you begin playing and stop it when you finish. You pay for the time played, rounded up to the next 30 minutes (minimum 1 hour): ₱150 first hour, +₱100 each extra hour, +₱75 for an extra half hour.</p>
<button class="w-full py-3 rounded-lg bg-primary text-on-primary font-title-sm text-title-sm active:scale-[0.99] transition-all" onclick="reserve()">Request Reservation</button><p class="font-body-sm text-body-sm text-outline text-center">Staff will confirm your request.</p></div>
</div>
<div class="fixed bottom-20 left-1/2 -translate-x-1/2 z-40 bg-on-surface text-surface-bright px-4 py-2.5 rounded-full shadow-lg flex items-center gap-2 opacity-0 pointer-events-none transition-all duration-300" id="toast"><span class="material-symbols-outlined text-secondary-container text-[18px]">check_circle</span><span class="font-label-md text-label-md" id="toast-message"></span></div>
<script>function est(){const v=document.getElementById('dur').value,open=v==='open';document.getElementById('open-note').classList.toggle('hidden',!open);document.getElementById('total-label').textContent=open?'Billing':'Estimated total';if(open){document.getElementById('total').textContent='By time played';return}const m=+v;const extra=m-60;const t=150+Math.floor(extra/60)*100+((extra%60)?75:0);document.getElementById('total').textContent='₱'+t}
function toast(m){const t=document.getElementById('toast');document.getElementById('toast-message').textContent=m;t.classList.remove('opacity-0');t.classList.add('opacity-100');setTimeout(()=>{t.classList.remove('opacity-100');t.classList.add('opacity-0')},3500)}
var busy=false;
async function reserve(){
 if(busy)return;
 var d=document.getElementById('rdate').value;if(!d){toast('Pick a date first');return}
 busy=true;
 try{
  var r=await fetch('api/reservations.php',{method:'POST',headers:{'Content-Type':'application/json'},
   body:JSON.stringify((function(){var v=document.getElementById('dur').value,b={table:document.getElementById('tbl').value,date:d,time:document.getElementById('rtime').value};if(v==='open')b.open=true;else b.mins=+v;return b})())});
  var j=await r.json();
  if(r.ok&&!j.error){toast('Request sent! Staff will confirm.');setTimeout(function(){location.href='receipt.php?type=resv&id='+j.id},900)}else{toast(j.error||'Could not send your request.')}
 }catch(e){toast('Network error. Please try again.')}
 busy=false}
function pick(n){document.getElementById('tbl').value=n;slotsUpdate();document.getElementById('reserve').scrollIntoView({behavior:'smooth'});toast(n+' selected')}

/* ---- live table status + the times already booked (api/availability.php) ---- */
var AV=null,BASEPILL='px-2 py-0.5 rounded-full font-label-sm text-label-sm';
function paintTables(list){
  list.forEach(function(t){
    var c=document.querySelector('[data-table="'+t.table+'"]');if(!c)return;
    var p=c.querySelector('[data-pill]'),n=c.querySelector('[data-note]');
    p.className=BASEPILL+(t.status==='available'?' bg-tertiary-fixed text-on-tertiary-fixed':'');
    p.style.background=t.status==='reserved'?'var(--warn-bg)':t.status==='playing'?'var(--bad-bg)':'';
    p.style.color=t.status==='reserved'?'var(--warn-fg)':t.status==='playing'?'var(--bad-fg)':'';
    p.textContent=t.label;n.textContent=t.note;
  });
}
async function availLoad(){
  var d=document.getElementById('rdate').value||'';
  try{
    var r=await fetch('api/availability.php'+(d?'?date='+encodeURIComponent(d):''),{cache:'no-store'});
    var j=await r.json();if(!r.ok||j.error)return;
    AV=j;paintTables(j.tables);slotsUpdate();
  }catch(e){}
}
function dayLabel(d){try{return new Date(d+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric'})}catch(e){return d}}
function slotsUpdate(){
  var box=document.getElementById('slots-text'),warn=document.getElementById('slots-warn');
  warn.classList.add('hidden');
  if(!AV){box.textContent='Loading...';return}
  var t=document.getElementById('tbl').value,d=document.getElementById('rdate').value||AV.date;
  if(d!==AV.date){box.textContent='Checking '+dayLabel(d)+'...';return}      // availLoad() fetches the newly picked date
  var list=AV.booked[t]||[];
  box.textContent=list.length?t+' on '+dayLabel(d)+':  '+list.map(function(x){return x.label}).join('   \u2022   '):t+' is free all day on '+dayLabel(d)+'.';
  var tm=document.getElementById('rtime').value,v=document.getElementById('dur').value;
  if(/^\d\d:\d\d$/.test(tm)){
    var s=(+tm.slice(0,2))*60+(+tm.slice(3)),e=v==='open'?AV.close_min:s+(+v);
    var hit=list.filter(function(x){return x.s<e&&x.e>s})[0];                 // same overlap rule the server uses
    if(hit){warn.textContent='That time overlaps a booking ('+hit.label+'). Please pick another time or table.';warn.classList.remove('hidden')}
  }
}
document.getElementById('rdate').addEventListener('change',function(){slotsUpdate();availLoad()});
['tbl','rtime','dur'].forEach(function(id){document.getElementById(id).addEventListener('change',slotsUpdate)});
document.getElementById('rtime').addEventListener('input',slotsUpdate);
document.addEventListener('visibilitychange',function(){if(!document.hidden)availLoad()});
setInterval(function(){if(!document.hidden)availLoad()},30000);
availLoad();</script></main><?php include __DIR__ . '/includes/nav.php'; ?></body></html>